            return 0;
        int ans[length];
        memset(ans, 0, sizeof(ans));
        for (int i = 1; i < length; i++) {
            if (s[i] == ')') {
                int j = i - 1 - ans[i - 1];
                if (j >= 0 && s[j] == '(') {
                    ans[i] = ans[i - 1] + 2;
                    if (j - 1 >= 0) {
                        ans[i] += ans[j - 1];
                    }
                }
            }
        }
        int ret = 0;
        for (int i = 0; i < length; i++)
            if (ans[i] > ret)
                ret = ans[i];
        return ret;
    }
};

